function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const allMajors = ['Computer Science', 'Mathematics', 'Physics', 'Biology', 'Chemistry'];
  const titles = ['Algorithms', 'Calculus', 'Mechanics', 'Genetics', 'Statistics', 'Optics', 'Databases', 'Ecology', 'Topology', 'Networks'];
  const names = ['Alice', 'Bob', 'Charlie', 'David', 'Eve', 'Frank', 'Grace', 'Heidi'];
  const semesters = ['Fall 2023', 'Spring 2023', 'Fall 2022', 'Spring 2024'];
  // GPA points follow the grade loosely, in steps of 0.5 so averages compare exactly.
  const points = { A: [4, 4, 3.5], B: [3.5, 3, 3], C: [2.5, 2], D: [1.5, 1], F: [0, 0.5] };
  const majors = allMajors.slice(0, small ? 1 + Math.floor(rand() * 2) : 5);
  const courses = [], required = {}, electives = {};
  let courseId = 100;
  for (const major of majors) {
    required[major] = []; electives[major] = [];
    const [m, el] = small ? [1 + Math.floor(rand() * 2), 1 + Math.floor(rand() * 3)] : [2 + Math.floor(rand() * 3), 2 + Math.floor(rand() * 4)];
    for (let i = 0; i < m + el; i++) {
      courseId += 1 + Math.floor(rand() * 2);
      const mandatory = i < m ? 'yes' : 'no';
      courses.push([courseId, pick(titles), pick([2, 3, 4]), major, mandatory]);
      (i < m ? required : electives)[major].push(courseId);
    }
  }
  for (let i = courses.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [courses[i], courses[j]] = [courses[j], courses[i]]; }
  const studentCount = small ? Math.floor(rand() * 4) : 200;
  const students = [], enrollments = [];
  const enroll = (id, course, grade) => enrollments.push([id, course, pick(semesters), grade, pick(points[grade])]);
  for (let id = 1; id <= studentCount; id++) {
    const major = pick(majors);
    students.push([id, pick(names), major]);
    // Strong students meet the grade rules most of the time; others break them in varied ways.
    const strong = rand() < 0.5;
    for (const course of required[major]) {
      if (!strong && rand() < 0.15) continue;
      enroll(id, course, strong || rand() < 0.6 ? 'A' : pick(['B', 'C']));
    }
    for (const course of electives[major]) {
      if (rand() < 0.3) continue;
      enroll(id, course, rand() < (strong ? 0.85 : 0.6) ? pick(['A', 'B']) : pick(['C', 'D']));
    }
    // Courses of other majors only affect the GPA; a few weak ones pull it under 2.5.
    const others = courses.filter(c => c[3] !== major).map(c => c[0]);
    const extra = small ? Math.floor(rand() * 2) : Math.floor(rand() * 4);
    for (let k = 0; k < extra && others.length; k++) {
      const course = others.splice(Math.floor(rand() * others.length), 1)[0];
      enroll(id, course, rand() < 0.5 ? pick(['D', 'F']) : pick(['A', 'B', 'C']));
    }
  }
  for (let i = enrollments.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [enrollments[i], enrollments[j]] = [enrollments[j], enrollments[i]]; }
  if (enrollments.length > 2000) enrollments.length = 2000;
  return [{ students, courses, enrollments }];
}
